public class OlaJava {
    public static void main(String[] args) {
        System.out.println("Olá, Java!");
    }
}

// Compilar: javac OlaJava.java
// Executar: java OlaJava

Object primeiro = new Object();
Object segundo = primeiro;
System.out.println(primeiro == segundo); // true

Set<String> nomes = new HashSet<>();
nomes.add("Ana");
nomes.add(new String("Ana"));
System.out.println(nomes.size()); // 1

CompletableFuture<String> nome = CompletableFuture.supplyAsync(() -> "Carlos");
CompletableFuture<Integer> total = CompletableFuture.supplyAsync(() -> 3);
String mensagem = nome.thenCombine(total,
    (n, t) -> n + " possui " + t + " agendamentos").join();
System.out.println(mensagem);
